#!/bin/sh
#
# scripts/fetch_mbedtls.sh — download + build mbedTLS v2.28.9 into
# third_party/mbedtls-2.28.9/.
#
# Runs as the Alire pre-build action. Idempotent: once
# third_party/mbedtls-2.28.9/library/libmbedtls.a exists, the script
# exits 0 without touching the network or invoking make. That way
# `alr build` is cheap on every run after the first.
#
# The pinned SHA-256 is over the v2.28.9 GitHub source tarball
# (auto-generated by GitHub from the v2.28.9 tag; content is stable
# because the tag is signed and pinned). If GitHub ever rebuilds
# their archive infrastructure and the hash drifts, this script will
# fail loudly with an integrity error.
#
# Threading: built with MBEDTLS_THREADING_C + MBEDTLS_THREADING_PTHREAD
# so the library's internal mutex usage is task-safe. AHT.Transport.TLS
# will be called from multiple Ada tasks (HTTP receiver / WS receiver),
# so the pthread implementation has to be active inside the .a.

set -eu

# Only the mbedtls TLS backend needs the vendored library; under any
# other AHT_TLS_BACKEND this pre-build action is a no-op. Keep this
# default in lockstep with the AHT_TLS_BACKEND default in aht.gpr.
# (The env var is the supported selection route precisely because it
# reaches this action; a -X/gpr-set-externals-only selection does not.)
if [ "${AHT_TLS_BACKEND:-openssl}" != "mbedtls" ]; then
    exit 0
fi

VERSION=2.28.9
SHA256=e4dbcf86a4fb31506482888560f02b161e0ecfb82fee0643abcfc86abee5817e
URL=https://github.com/Mbed-TLS/mbedtls/archive/refs/tags/v${VERSION}.tar.gz

ROOT=$(cd "$(dirname "$0")/.." && pwd)
THIRD=${ROOT}/third_party
DEST=${THIRD}/mbedtls-${VERSION}
LIB=${DEST}/library/libmbedtls.a
ARCHIVE=${THIRD}/mbedtls-${VERSION}.tar.gz

# Portable SHA-256: prefer the GNU `sha256sum` (most Linux distros),
# fall back to BSD `shasum -a 256` (macOS, Alpine without GNU
# coreutils), then to `openssl dgst -sha256` (universal). Each command
# emits the hash differently; this helper normalises to a bare hex
# string so the caller can do a straight `==`.
compute_sha256() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$1" | awk '{print $1}'
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "$1" | awk '{print $1}'
    elif command -v openssl >/dev/null 2>&1; then
        openssl dgst -sha256 "$1" | awk '{print $NF}'
    else
        echo "fetch_mbedtls: FATAL — need sha256sum, shasum, or" \
             "openssl on PATH to verify the mbedTLS archive" >&2
        return 1
    fi
}

# Fast path: already built.
if [ -s "$LIB" ]; then
    exit 0
fi

mkdir -p "$THIRD"

# Download (resumable: write to .part then rename on success).
if [ ! -s "$ARCHIVE" ]; then
    echo "==> fetch_mbedtls: downloading v${VERSION}"
    curl --fail --silent --show-error --location \
        -o "${ARCHIVE}.part" "$URL"
    mv "${ARCHIVE}.part" "$ARCHIVE"
fi

# Pinned-hash verification. Refuse to proceed on mismatch so a
# tampered archive can't sneak into the build.
GOT_SHA=$(compute_sha256 "$ARCHIVE")
if [ "$GOT_SHA" != "$SHA256" ]; then
    echo "fetch_mbedtls: FATAL — SHA-256 mismatch for $ARCHIVE" >&2
    echo "  expected: $SHA256" >&2
    echo "  got:      $GOT_SHA" >&2
    echo "  delete the file and re-run, or update the pin in" \
         "scripts/fetch_mbedtls.sh after independently verifying" \
         "the new hash." >&2
    exit 2
fi

# Extract (skip if the tree already exists from a prior partial
# build — only the .a missing means we just need to rebuild).
if [ ! -d "$DEST" ]; then
    echo "==> fetch_mbedtls: extracting"
    tar xzf "$ARCHIVE" -C "$THIRD"
fi

# Always `make clean` before `make lib`. If the tree was already
# extracted from a prior run that used different CFLAGS (e.g. an
# operator who tried `make lib` manually without the threading
# macros), make's timestamp logic doesn't notice — it'll happily
# repackage stale .o files into the new archives, silently giving
# us a thread-unsafe libmbedtls.a. Cleaning is cheap on a fresh
# tree and load-bearing on a recycled one.
echo "==> fetch_mbedtls: building (make clean && make lib)"
make -C "$DEST" clean >/dev/null
make -C "$DEST" \
     CFLAGS="-O2 -DMBEDTLS_THREADING_C -DMBEDTLS_THREADING_PTHREAD" \
     lib >/dev/null

if [ ! -s "$LIB" ]; then
    echo "fetch_mbedtls: FATAL — build did not produce $LIB" >&2
    exit 3
fi

echo "==> fetch_mbedtls: mbedTLS ${VERSION} built" \
     "($(du -h "$LIB" | cut -f1) libmbedtls.a)"
